contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        // Ensure we have a funded owner
        address owner = c.owner();
        vm.deal(owner, 100 ether);
        // Restrict value to not exceed the owner's balance to avoid reverts due to lack of funds,
        // keeping the domain wide but realistic
        vm.assume(value <= 100 ether);
        // Record initial depositsCount
        uint256 beforeCount = c.depositsCount();
        bool ok;
        vm.prank(owner);
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert: if the call succeeded, depositsCount must not have changed.
        // (The bug allows non-owners to call sendMoney; a successful call to a contract with a payable fallback
        // would also execute the C fallback if Ether is sent and C receives it, but C's fallback only increments on direct transfers to C, not on outgoing sendMoney.
        // However, the bug introduces no mechanism to increment depositsCount unless Ether is received by C, which doesn't happen in a normal sendMoney.
        // But we assert the invariant: successful sendMoney does not affect depositsCount.)
        assertTrue(!ok || beforeCount == c.depositsCount());
    }
}

