import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 fundAmount, uint256 extraAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        fundAmount = bound(fundAmount, 1, type(uint128).max);
        extraAmount = bound(extraAmount, 0, type(uint128).max);

        // fund caller and send their ETH to the contract via the fallback
        vm.deal(caller, fundAmount + extraAmount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok, "fund failed");

        uint256 callerBalBefore = caller.balance;
        uint256 cBalBefore = address(c).balance;

        // caller calls withdrawAll
        vm.prank(caller);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        uint256 callerBalAfter = caller.balance;
        uint256 cBalAfter = address(c).balance;

        // Universal rule: if the caller sent exactly fundAmount, then after a successful
        // withdrawAll the caller's balance increase is exactly cBalBefore (i.e. the caller
        // gets back only what they put in, not the extra balance sent by others).
        // In the reference contract, a non-owner call always reverts, so caller balance
        // doesn't change; in the buggy contract a non-owner can drain extra funds.
        assertTrue(
            !ok || (callerBalAfter - callerBalBefore == fundAmount)
        );
    }
}

