contract InvMutTest is Test {
    C c;
    address owner = address(0x1234);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialDeposit) public {
        // Bound the deposit to a reasonable non-zero amount to ensure the contract has a balance before withdrawAll
        bound(initialDeposit, 1 wei, 1000 ether);

        // Prank as the owner for all setup and the withdrawAll call
        vm.prank(owner);
        c = new C();

        // Seed the contract with Ether via the fallback (requires prank as anyone, but we can just deal to owner and prank)
        vm.deal(owner, initialDeposit);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: initialDeposit}("");
        require(success, "Initial deposit failed");

        // Record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "Precondition: contract must have balance");

        // Owner calls withdrawAll
        vm.prank(owner);
        try c.withdrawAll() {
            // Reference: succeeds
            // Mutant: selfdestruct also succeeds (no revert), but destroys the contract
        } catch {
            // Reference never reverts here; mutant might or might not revert depending on implementation.
            // We handle the difference through post-condition below.
        }

        // Post-condition: the contract's balance must be zero after a successful withdrawAll
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, 0, "Balance must be zero after withdrawAll");

        // The distinguishing property: the contract must still be callable (non-reverting) after withdrawAll.
        // A selfdestructed contract will have zero code, so a call to it will revert.
        // We make a zero-value call to the fallback (or any function) and check it does not revert.
        (bool callOk, ) = address(c).call{value: 0}("");
        assertTrue(callOk, "Contract must remain callable after withdrawAll (selfdestruct reverts)");
    }
